def find_inverse_permutation(n, p):
    parent = list(range(n + 1))

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        rootX = find(x)
        rootY = find(y)
        if rootX != rootY:
            parent[rootX] = rootY

    # Group elements that belong to the same cycle in p
    for i in range(1, n + 1):
        union(p[i - 1], i)

    # Create the inverse permutation q
    q = [-1] * (n + 1)
    for i in range(1, n + 1):
        q[find(i)] = p[i - 1]

    # Check if the inverse permutation is valid
    for i in range(1, n + 1):
        if q[q[i]] != i:
            return [-1]

    return q[1:]

