def find_inverse_permutation(n, p):
    index_map = {p[i]: i for i in range(n)}
    temp = [-1] * n
    visited = [False] * n

    def dfs(index):
        if visited[index]:
            return []
        visited[index] = True
        next_index = p[index]
        cycle = [index + 1]

        while next_index != index:
            if visited[next_index - 1]:
                return []
            visited[next_index - 1] = True
            cycle.append(next_index)
            next_index = p[next_index - 1]

        if len(cycle) % 2 == 1:
            return []

        for i in range(len(cycle)):
            temp[cycle[i] - 1] = cycle[(i + len(cycle) // 2) % len(cycle)]

        return cycle

    for i in range(n):
        if not visited[i]:
            result = dfs(i)
            if not result:
                return [-1]

    return [x + 1 for x in temp]

