def find_inverse_permutation(n, p):
    if n == 1:
        return [1]

    index_map = {p[i]: i for i in range(n)}
    temp = [-1] * n

    for i in range(n):
        next_index = p[i] - 1
        if next_index >= n or temp[next_index] != -1:
            return [-1]

        while temp[next_index] == -1:
            temp[next_index] = i + 1
            next_index = p[next_index] - 1

        if temp[next_index] != i + 1:
            return [-1]

    q = [0] * n
    for i in range(n):
        q[index_map[i + 1]] = temp[i]

    return q

