def find_inverse_permutation(n, p):
    index_map = {p[i]: i for i in range(n)}
    temp = [-1] * n
    visited = [False] * n

    def dfs(index):
        if visited[index]:
            return []
        visited[index] = True
        next_index = p[index]
        cycle = [index + 1]
        while next_index != index:
            visited[next_index - 1] = True
            cycle.append(next_index)
            next_index = p[next_index - 1]
        return cycle

    for i in range(n):
        if not visited[i]:
            cycle = dfs(i)
            if len(cycle) % 2 == 1:
                return -1
            half_cycle_length = len(cycle) // 2
            for j in range(half_cycle_length):
                temp[cycle[j] - 1] = cycle[half_cycle_length + j]
                temp[cycle[half_cycle_length + j] - 1] = cycle[j]

    return ' '.join(map(str, temp))

